		b.add("site.jjkcraft.modulo.inhuman_makyo", "The Inhuman Makyo");
		b.add("site.jjkcraft.modulo.chaos_arena", "Shinjuku Ruins: The Duel");
		b.add("entity.jjkcraft.modulo.trafficker", "The Trafficker");
		b.add("entity.jjkcraft.modulo.toranosuke", "Toranosuke");
		b.add("entity.jjkcraft.modulo.masaki_takeda", "Masaki Takeda");
		b.add("entity.jjkcraft.modulo.skin_guardian", "Skin-Sewn Guardian");
		b.add("entity.jjkcraft.modulo.maru_duel", "Maru (Chaos)");
		b.add("entity.jjkcraft.modulo.dabura", "Dabura Karaba");
		b.add("entity.jjkcraft.modulo.dabura_scene", "Dabura Karaba");
		b.add("entity.jjkcraft.modulo.mahoraga", "Eight-Handled Sword Divergent Sila Divine General Mahoraga");
		b.add("domain.modulo.reverse_transcendence", "Otherworld Between Darkness and Light: Reverse Transcendence");
		b.add("domain.modulo.reverse_transcendence.desc", "Dabura Karaba's domain. Its sure-hit effect is never shown in the story; here, light falls on everyone inside.");
		b.add("technique.jjkcraft.batto_sword_drawing", "New Shadow Style: Batto Sword Drawing");
		b.add("technique.jjkcraft.batto_sword_drawing.desc", "The fastest draw of the New Shadow Style. With Honoyagi the blade leaves its scabbard in sparks and the cut sweeps out as fire.");
		b.add("technique.jjkcraft.mul_lance", "Mul Lance");
		b.add("technique.jjkcraft.mul_lance.desc", "A Rumelian blade throws a lance of Mul energy. Paid in Mul energy, not cursed energy.");
		b.add("item.jjkcraft.honoyagi.desc", "Tsurugi Okkotsu's katana. Sparks between scabbard and guard set its blade alight. A medium: it pays for its technique with its own durability.");
		b.add("item.jjkcraft.rumelian_blade.desc", "A forked Rumelian sword with Mul set in its hilt. Lends Mul Lance, paid in Mul energy.");
		b.add("advancements.jjkcraft.modulo.root.description", "Board the Naunax during the Naunax Descent");
		b.add("advancements.jjkcraft.modulo.root.title", "Special Grade Incident");
		b.add("advancements.jjkcraft.modulo.epilogue.description", "See the Modulo story to its end");
		b.add("advancements.jjkcraft.modulo.epilogue.title", "A Bright Future");
		b.add("objective.jjkcraft.modulo.special_grade_incident.board", "Board the Naunax while it hangs above the badlands");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.intro_1", "2086, sixty-eight years after the Culling Game. A mothership carrying nearly fifty thousand Simurians hangs high above Nevada.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.intro_2", "The United States has left all dealings with them to Japan. The Jujutsu Inspector General calls it a special grade incident.");
		b.add("objective.jjkcraft.modulo.special_grade_incident.maru", "Meet the Simurian inspector in the envoys' hall");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.maru_1", "You must be one of Japan's sorcerers. I'm Marulu Val Vol Yelvori. Maru is fine.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.maru_2", "My people want to know whether we can live beside you. I'm to go with your sorcerers and see for myself.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.maru_3", "The inspector will neither help nor hinder your work. Those are his orders.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.maru_4", "Take the gate down to Kyoto. I'll follow.");
		b.add("objective.jjkcraft.modulo.special_grade_incident.kyoto", "Take the ship's gate down to Kyoto Jujutsu High");
		b.add("objective.jjkcraft.modulo.special_grade_incident.usami", "Hear Usami's briefing");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.usami_1", "Children are vanishing in Kyoto. Japanese citizens are taken and sold, because their cursed energy can be burned for power.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.usami_2", "Yuka and Tsurugi Okkotsu will look into it. The Simurian inspector goes with you; he is here under the Security Treaty.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.usami_3", "It is an investigation, not a fight. Try to remember that.");
		b.add("objective.jjkcraft.modulo.special_grade_incident.yuka", "Talk to Yuka Okkotsu");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.yuka_1", "An inspector? Fine. Just don't slow us down.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.yuka_2", "I work faster alone.");
		b.add("dialogue.jjkcraft.modulo.special_grade_incident.yuka_3", "Ignore my brother. Maru, you're with us. Let's find those kids.");
		b.add("mission.jjkcraft.modulo.special_grade_incident", "Special Grade Incident");
		b.add("mission.jjkcraft.modulo.special_grade_incident.summary", "A ship of Simurians arrives, and an inspector joins two young sorcerers.");
		b.add("objective.jjkcraft.modulo.kyoto_abductions.path_1", "Walk the guiding road: first lantern");
		b.add("dialogue.jjkcraft.modulo.kyoto_abductions.intro_1", "This road is under a gaze-manipulation curse. It nudges whoever walks it down one path.");
		b.add("dialogue.jjkcraft.modulo.kyoto_abductions.intro_2", "Walk it in the order it wants, and we'll see where it leads.");
		b.add("objective.jjkcraft.modulo.kyoto_abductions.path_2", "Walk the guiding road: second lantern");
		b.add("objective.jjkcraft.modulo.kyoto_abductions.path_3", "Walk the guiding road: third lantern");
		b.add("dialogue.jjkcraft.modulo.kyoto_abductions.hands", "At the end of the road, hands reach out of the dark: a barrier technique built to carry people away.");
		b.add("objective.jjkcraft.modulo.kyoto_abductions.warehouse", "Find the talisman warehouse");
		b.add("objective.jjkcraft.modulo.kyoto_abductions.fight", "Defeat the trafficker");
		b.add("dialogue.jjkcraft.modulo.kyoto_abductions.fight", "He moves through his talismans. Burn them, or watch your back.");
		b.add("objective.jjkcraft.modulo.kyoto_abductions.report", "Report to Usami");
		b.add("dialogue.jjkcraft.modulo.kyoto_abductions.report_1", "The children are alive. Good work.");
		b.add("dialogue.jjkcraft.modulo.kyoto_abductions.report_2", "He says he was quitting the trade, because the aliens will soon show the world how weak our sorcerers have become. Keep that to yourself.");
		b.add("mission.jjkcraft.modulo.kyoto_abductions", "The Kyoto Abductions");
		b.add("mission.jjkcraft.modulo.kyoto_abductions.summary", "A road that steers children into a barrier, and the man who sells them.");
		b.add("objective.jjkcraft.modulo.swimming_through_the_forest.river", "Go to the dry river in Gifu");
		b.add("dialogue.jjkcraft.modulo.swimming_through_the_forest.intro", "Villagers in the mountains of Gifu keep being attacked. Something big came down the river valley.");
		b.add("objective.jjkcraft.modulo.swimming_through_the_forest.osada", "Talk to Osada");
		b.add("dialogue.jjkcraft.modulo.swimming_through_the_forest.osada_1", "I was a sorcerer once. The killer isn't a curse. It's a tiger. Toranosuke.");
		b.add("dialogue.jjkcraft.modulo.swimming_through_the_forest.osada_2", "They restored the solar plant on the mountain, and the heat dried his river. He came down for water and found people.");
		b.add("dialogue.jjkcraft.modulo.swimming_through_the_forest.osada_3", "I wanted to save him. Keep him far from town.");
		b.add("dialogue.jjkcraft.modulo.swimming_through_the_forest.osada_4", "A beast that has eaten people has to be put down.");
		b.add("objective.jjkcraft.modulo.swimming_through_the_forest.tiger", "Stop Toranosuke");
		b.add("objective.jjkcraft.modulo.swimming_through_the_forest.cub", "Bring the tiger cub to Osada");
		b.add("dialogue.jjkcraft.modulo.swimming_through_the_forest.cub_1", "Raise this one well. Don't let it become another Toranosuke.");
		b.add("dialogue.jjkcraft.modulo.swimming_through_the_forest.cub_2", "I will. I promise.");
		b.add("mission.jjkcraft.modulo.swimming_through_the_forest", "Swimming Through the Forest");
		b.add("mission.jjkcraft.modulo.swimming_through_the_forest.summary", "A tiger comes down from the mountain after its river runs dry.");
		b.add("objective.jjkcraft.modulo.the_boy_who_kept_repeating.mino", "Hear Mino's report");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.mino_1", "Every year the same boy enrols at Shuei Elementary under a new name. Masayoshi, then Masaaki, now Masaki. His face never changes.");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.mino_2", "Each year he moves away with his family before second grade. Each year he comes back.");
		b.add("objective.jjkcraft.modulo.the_boy_who_kept_repeating.school", "Go to Shuei Elementary");
		b.add("objective.jjkcraft.modulo.the_boy_who_kept_repeating.boy", "Talk to the boy");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.boy_1", "I found my mother dead three years ago. I begged her to let me stay in first grade forever.");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.boy_2", "Something has looked after me ever since. It never hurts me.");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.boy_3", "Then let us be your neighbors. Someone who understands why your feelings matter.");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.boy_4", "Tsurugi, listen: there are five bodies buried at Masaki Takeda's house. The real Masaki Takeda is an old man.");
		b.add("objective.jjkcraft.modulo.the_boy_who_kept_repeating.fight", "Defeat Masaki Takeda");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.fight_1", "Marmalade Boy: he sews with human skin. Himself, his guardian, anything.");
		b.add("dialogue.jjkcraft.modulo.the_boy_who_kept_repeating.fight_2", "If he hides inside that guardian, tear him out of it.");
		b.add("mission.jjkcraft.modulo.the_boy_who_kept_repeating", "The Boy Who Kept Repeating");
		b.add("mission.jjkcraft.modulo.the_boy_who_kept_repeating.summary", "A first-grader who never grows older, and the curse user wearing a child's skin.");
		b.add("objective.jjkcraft.modulo.berserk.pool", "Find Maru by the school pool");
		b.add("dialogue.jjkcraft.modulo.berserk.intro_1", "Water lifts out of a cup and hangs in the air. Across town, an unconscious Maru opens his third eye.");
		b.add("dialogue.jjkcraft.modulo.berserk.intro_2", "His technique, Chaos, bends the laws of order: gravity, heat, the path of a thrown stone.");
		b.add("objective.jjkcraft.modulo.berserk.maru", "Call Maru back");
		b.add("dialogue.jjkcraft.modulo.berserk.maru_1", "Maru turns his third eye on you. Your thoughts slide sideways.");
		b.add("dialogue.jjkcraft.modulo.berserk.maru_2", "You remind him what he said to the boy: that you would be neighbors.");
		b.add("dialogue.jjkcraft.modulo.berserk.maru_3", "...Neighbors. Did I... hurt anyone?");
		b.add("objective.jjkcraft.modulo.berserk.cross", "Talk to the Simurian on the roof");
		b.add("dialogue.jjkcraft.modulo.berserk.cross_1", "I am Cross, his brother. Our technique is shared; when he uses it without thinking, I feel it.");
		b.add("dialogue.jjkcraft.modulo.berserk.cross_2", "Some of us would have welcomed a reason for war today. Don't give them one.");
		b.add("objective.jjkcraft.modulo.berserk.usami", "Report to Usami");
		b.add("dialogue.jjkcraft.modulo.berserk.usami_1", "So the inspector is an alien. The secrecy is over, then.");
		b.add("dialogue.jjkcraft.modulo.berserk.usami_2", "One of their envoys could conquer Japan alone. His name is Dabura Karaba. Remember it.");
		b.add("mission.jjkcraft.modulo.berserk", "Berserk");
		b.add("mission.jjkcraft.modulo.berserk.summary", "Maru's third eye opens, and Chaos answers before he does.");
		b.add("objective.jjkcraft.modulo.cultural_exchange.beach", "Go to the beach");
		b.add("dialogue.jjkcraft.modulo.cultural_exchange.intro", "The Simurians want to make takoyaki themselves. We need wancha octopus: one tentacle, all eight flavors. Watch the jellyfish.");
		b.add("objective.jjkcraft.modulo.cultural_exchange.catch", "Catch a wancha octopus and show Tsurugi (%s/%s)");
		b.add("dialogue.jjkcraft.modulo.cultural_exchange.catch_1", "Not bad. Maru came up with a bigger one, covered in stings. He refuses a rash guard.");
		b.add("objective.jjkcraft.modulo.cultural_exchange.party", "Join the takoyaki party at Kyoto Jujutsu High");
		b.add("dialogue.jjkcraft.modulo.cultural_exchange.party_1", "I'm the nutritionist and I'm not cooking the main course? Fine. What on earth is this octopus?");
		b.add("dialogue.jjkcraft.modulo.cultural_exchange.party_2", "Hot! It's hot! It's wonderful!");
		b.add("dialogue.jjkcraft.modulo.cultural_exchange.party_3", "Take some with you. There is far too much.");
		b.add("mission.jjkcraft.modulo.cultural_exchange", "Cultural Exchange");
		b.add("mission.jjkcraft.modulo.cultural_exchange.summary", "A takoyaki party, and the octopus that has the flavor of all eight tentacles in one.");
		b.add("objective.jjkcraft.modulo.inhuman_makyo.core", "Visit the Naunax's Mul core");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.core_1", "This is Mul, the ore our conflict was fought over. It turns rolloluca into any kind of energy.");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.core_2", "Rolloluca is their word for cursed energy. This ship runs on cursed energy. If that gets out, people will be hunted for it again.");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.core_3", "Try it yourself: pour your cursed energy into a piece of Mul.");
		b.add("objective.jjkcraft.modulo.inhuman_makyo.mul", "Make Mul energy at the core (%s/%s)");
		b.add("objective.jjkcraft.modulo.inhuman_makyo.barrier", "Go to Tokyo's barrier line");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.intro_1", "In Tokyo, a Simurian weeps from his third eye: sorcerers are exorcising cursed spirits, and to Rumelians they look like Kalyans, the sacred beasts.");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.intro_2", "In the confusion, Cross is shot.");
		b.add("objective.jjkcraft.modulo.inhuman_makyo.usami", "Hear what happened");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.usami_1", "The Rumelians demand Tokyo, as a nation where cursed spirits are protected. We cannot stop exorcising them; they would spill out of Tokyo.");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.usami_2", "They have challenged us to a duel, the Deskunte way. Japan has chosen its champion: Yuka Okkotsu.");
		b.add("objective.jjkcraft.modulo.inhuman_makyo.dabura", "Face Dabura");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.dabura_1", "I fight for the Rumel tribe. On Simuria, a dispute is settled by one champion against another.");
		b.add("dialogue.jjkcraft.modulo.inhuman_makyo.dabura_2", "Bring your champion to the ruins of your old capital.");
		b.add("mission.jjkcraft.modulo.inhuman_makyo", "Inhuman Makyo");
		b.add("mission.jjkcraft.modulo.inhuman_makyo.summary", "The ship runs on cursed energy, curses look like Kalyans, and a duel is demanded.");
		b.add("objective.jjkcraft.modulo.forbidden_technique.makyo", "Go to the Inhuman Makyo");
		b.add("dialogue.jjkcraft.modulo.forbidden_technique.intro_1", "Yuka forms the seal of the Ten Shadows and calls the shikigami no one in her line has ever tamed: Mahoraga.");
		b.add("dialogue.jjkcraft.modulo.forbidden_technique.intro_2", "Ten Shadows' strongest shikigami. Every time something hurts it, its wheel turns, and it adapts.");
		b.add("objective.jjkcraft.modulo.forbidden_technique.hold", "Hold off the cursed spirits fleeing Tokyo while Mahoraga adapts");
		b.add("objective.jjkcraft.modulo.forbidden_technique.yuka", "Check on Yuka");
		b.add("dialogue.jjkcraft.modulo.forbidden_technique.yuka_1", "It adapted to his Light. He can't touch it now.");
		b.add("dialogue.jjkcraft.modulo.forbidden_technique.yuka_2", "I'm fine. I'm fine. Go and find my brother.");
		b.add("mission.jjkcraft.modulo.forbidden_technique", "The Forbidden Technique Unleashed");
		b.add("mission.jjkcraft.modulo.forbidden_technique.summary", "Yuka summons Mahoraga against Dabura, and it begins to adapt.");
		b.add("objective.jjkcraft.modulo.chaos_and_harmony.arena", "Go to the duel in the Shinjuku ruins");
		b.add("dialogue.jjkcraft.modulo.chaos_and_harmony.intro", "I asked Maru to take his people away so Yuka wouldn't have to die fighting. He said no. So we fight.");
		b.add("objective.jjkcraft.modulo.chaos_and_harmony.choose", "Duel Maru yourself, or let Tsurugi fight?");
		b.add("objective.jjkcraft.modulo.chaos_and_harmony.duel", "Duel Maru: Chaos turns gravity over");
		b.add("dialogue.jjkcraft.modulo.chaos_and_harmony.duel", "Chaos and Harmony. Both of them, then.");
		b.add("objective.jjkcraft.modulo.chaos_and_harmony.watch", "Watch Tsurugi and Maru fight (%s s)");
		b.add("dialogue.jjkcraft.modulo.chaos_and_harmony.watch", "Gravity tips over. Rika rises behind Tsurugi. At the last moment he lets go of his katana and is cut down.");
		b.add("objective.jjkcraft.modulo.chaos_and_harmony.after", "Talk to Tsurugi");
		b.add("dialogue.jjkcraft.modulo.chaos_and_harmony.after_1", "A future where I won didn't feel right. I can't explain it better than that.");
		b.add("dialogue.jjkcraft.modulo.chaos_and_harmony.after_2", "Take Honoyagi for now. Its own energy pays for its cuts, so even I can draw it.");
		b.add("mission.jjkcraft.modulo.chaos_and_harmony", "Chaos and Harmony");
		b.add("mission.jjkcraft.modulo.chaos_and_harmony.summary", "Two older brothers duel: Tsurugi, and Maru with both his techniques.");
		b.add("objective.jjkcraft.modulo.ritual_of_harmony.makyo", "Return to the Inhuman Makyo");
		b.add("dialogue.jjkcraft.modulo.ritual_of_harmony.intro", "Dabura understands Reverse Cursed Technique by watching it, builds a barrier by watching one, and pours positive energy into his Light.");
		b.add("objective.jjkcraft.modulo.ritual_of_harmony.dabura", "Defeat Dabura Karaba (bring up to four sorcerers)");
		b.add("dialogue.jjkcraft.modulo.ritual_of_harmony.fight_1", "Light, and its reversal. Let us see which of us is the warrior.");
		b.add("dialogue.jjkcraft.modulo.ritual_of_harmony.fight_2", "When the black mass grows in his hands, get something solid between you and him.");
		b.add("objective.jjkcraft.modulo.ritual_of_harmony.ritual", "Talk to Maru");
		b.add("dialogue.jjkcraft.modulo.ritual_of_harmony.ritual_1", "My Harmony took Dabura home. He has a sister to free and a friend to bury.");
		b.add("dialogue.jjkcraft.modulo.ritual_of_harmony.ritual_2", "I meant to make a world where cursed spirits are never born. Itadori said it cannot be done by taking cursed energy from Japan alone.");
		b.add("dialogue.jjkcraft.modulo.ritual_of_harmony.ritual_3", "Rumelians, Kalyans and cursed spirits share one color of soul. That is why we mistook them. I will scatter it.");
		b.add("mission.jjkcraft.modulo.ritual_of_harmony", "Ritual of Harmony");
		b.add("mission.jjkcraft.modulo.ritual_of_harmony.summary", "Dabura reaches the summit of jujutsu; Maru looks for a world without curses.");
		b.add("objective.jjkcraft.modulo.a_bright_future.kyoto", "Go to Kyoto Jujutsu High");
		b.add("objective.jjkcraft.modulo.a_bright_future.watch", "A bright future");
		b.add("objective.jjkcraft.modulo.a_bright_future.kyoko", "Talk to Kyoko Tomoe");
		b.add("dialogue.jjkcraft.modulo.a_bright_future.kyoko_1", "Yuka's headaches are gone. Completely gone.");
		b.add("dialogue.jjkcraft.modulo.a_bright_future.kyoko_2", "Itadori came by and left something with the school. He asked that it go to someone who will keep it safe.");
		b.add("mission.jjkcraft.modulo.a_bright_future", "A Bright Future");
		b.add("mission.jjkcraft.modulo.a_bright_future.summary", "The ritual ends. Tokyo's cursed spirits rest, and two peoples learn to live together.");
		b.add("epilogue.jjkcraft.modulo.1", "The Ritual of Harmony ends. Across Tokyo, cursed spirits come apart into motes of light and rise.");
		b.add("epilogue.jjkcraft.modulo.2", "Yuka wakes as Mahoraga's wheel falls and melts into shadow. The pain in her head is gone.");
		b.add("epilogue.jjkcraft.modulo.3", "On Simuria, Dabura and Spejo walk into the chieftain's hall. The Deskunte kneel to a new chief, and Dura is buried as a hero.");
		b.add("epilogue.jjkcraft.modulo.4", "Aboard the Naunax, the Rumelians vote to keep living beside the Kalyans: they are family.");
		b.add("epilogue.jjkcraft.modulo.5", "No new sorcerers will be born. Yuji Itadori decides that when he dies, he will become a cursed object, so the energy can be taken back if it is ever needed.");
		b.add("epilogue.jjkcraft.modulo.6", "In Kyoto, sorcerers and Simurians play catch.");
		b.add("npc.jjkcraft.modulo.maru", "Maru");
		b.add("npc.jjkcraft.modulo.maru.idle", "Shall I bring you to the ship? Sneak and ask. My Harmony can find the way.");
		b.add("npc.jjkcraft.modulo.cross", "Cross");
		b.add("npc.jjkcraft.modulo.cross.idle", "My brother trusts too easily.");
		b.add("npc.jjkcraft.modulo.yuka", "Yuka Okkotsu");
		b.add("npc.jjkcraft.modulo.yuka.idle", "I'll get that ring back one day. You'll see.");
		b.add("npc.jjkcraft.modulo.tsurugi", "Tsurugi Okkotsu");
		b.add("npc.jjkcraft.modulo.tsurugi.idle", "I need to get stronger. Strong enough to give it back.");
		b.add("npc.jjkcraft.modulo.usami", "Kou Usami");
		b.add("npc.jjkcraft.modulo.usami.idle", "War with them must be avoided at any cost.");
		b.add("npc.jjkcraft.modulo.mino", "Mino");
		b.add("npc.jjkcraft.modulo.mino.idle", "Please tell me someone read the treaty.");
		b.add("npc.jjkcraft.modulo.kyoko_tomoe", "Kyoko Tomoe");
